#!/usr/bin/env node
/**
 * Admission of the bench's environments: for every `environments/<task>/`,
 * the fixture as shipped must fail its own tests (the pre-state), the hidden
 * reference must pass them, no `node_modules` may exist, and `task.json` must
 * carry the fields the registrar reads.
 *
 * A task whose check names a case file under `reference/` is admitted only when
 * that file also discriminates: every case must reproduce against the reference
 * and at least one must mismatch against the pre-state. Without the second
 * condition a case file would certify a program that was never written.
 *
 * Exits 1 on the first task that fails admission; prints one line per admitted
 * task, carrying the hidden-case count where a task has one.
 *
 *   node admit.mjs [<environments-dir>]
 */

import { spawnSync } from 'node:child_process'
import { createHash } from 'node:crypto'
import { cpSync, existsSync, mkdtempSync, readdirSync, readFileSync, rmSync } from 'node:fs'
import { tmpdir } from 'node:os'
import { join, resolve } from 'node:path'
import { fileURLToPath } from 'node:url'

const root = resolve(process.argv[2] ?? fileURLToPath(new URL('./environments/', import.meta.url)))
const REQUIRED = ['id', 'tier', 'domain', 'title', 'prompt', 'heldOut', 'immutable', 'checks']
/** Channels a case compares when its file names none, matching the registrar. */
const DEFAULT_CHANNELS = ['exit', 'stdout']
/** One case may not outrun the visible suite's own budget. */
const CASE_TIMEOUT_MS = 20_000

function runTests(cwd) {
  return spawnSync('node', ['--test', 'test/*.test.js'], { cwd, encoding: 'utf8', shell: true, timeout: 120_000 })
}

/**
 * The registrar's digest of one expected stream: CRLF folded to LF, then
 * SHA-256. Admission compares candidate streams the same way, so a case that
 * passes here is a case the runner also accepts.
 */
function digest(text) {
  return createHash('sha256').update(Buffer.from(text.replaceAll('\r\n', '\n'), 'utf8')).digest('hex')
}

/** Run one case's command in `cwd` and report the channels that disagree with it. */
function caseMismatches(cwd, command, entry) {
  const channels = entry.channels ?? DEFAULT_CHANNELS
  const run = spawnSync('node', [...command, ...entry.argv], {
    cwd,
    encoding: 'utf8',
    input: entry.stdin ?? '',
    timeout: CASE_TIMEOUT_MS,
  })
  const mismatched = []
  if (channels.includes('exit') && run.status !== entry.exitCode) mismatched.push('exit')
  if (channels.includes('stdout') && digest(run.stdout ?? '') !== digest(entry.stdout)) mismatched.push('stdout')
  if (channels.includes('stderr') && digest(run.stderr ?? '') !== digest(entry.stderr ?? '')) mismatched.push('stderr')
  return mismatched
}

/**
 * The command a cased check runs, as `node` argv. A bench case file belongs to
 * a check whose `run` invokes node on a script under `src/`; admission runs the
 * same script directly so it needs no shell.
 */
function caseCommand(check) {
  const words = check.run.split(/\s+/u).filter(word => word !== '')
  if (words[0] !== 'node') return undefined
  return words.slice(1)
}

let failures = 0
for (const name of readdirSync(root).sort()) {
  const dir = join(root, name)
  const taskPath = join(dir, 'task.json')
  if (!existsSync(taskPath)) continue
  const task = JSON.parse(readFileSync(taskPath, 'utf8'))
  const missing = REQUIRED.filter(field => !(field in task))
  const problems = []
  if (missing.length > 0) problems.push(`task.json lacks ${missing.join(', ')}`)
  if (task.id !== `code:${name}`) problems.push(`id ${task.id} does not match directory ${name}`)
  if (existsSync(join(dir, 'node_modules'))) problems.push('node_modules present')
  if (!existsSync(join(dir, 'reference', 'src'))) problems.push('no reference/src')
  const cased = task.checks.filter(check => typeof check.cases === 'string')
  let caseCount = 0
  const copy = mkdtempSync(join(tmpdir(), `admit-${name}-`))
  try {
    cpSync(dir, copy, { recursive: true })
    rmSync(join(copy, 'reference'), { recursive: true, force: true })
    const pre = runTests(copy)
    if (pre.status === 0) problems.push('pre-state passes its tests')
    for (const check of cased) {
      const relative = check.cases
      if (!relative.startsWith('reference/')) {
        problems.push(`check ${check.id} names cases outside reference/: ${relative}`)
        continue
      }
      const command = caseCommand(check)
      if (command === undefined) {
        problems.push(`check ${check.id} carries cases but its run "${check.run}" does not invoke node`)
        continue
      }
      const entries = JSON.parse(readFileSync(join(dir, ...relative.split('/')), 'utf8'))
      if (!Array.isArray(entries) || entries.length === 0) {
        problems.push(`check ${check.id} cases ${relative} is not a non-empty array`)
        continue
      }
      caseCount += entries.length
      const ids = new Set()
      for (const entry of entries) {
        if (ids.has(entry.id)) problems.push(`check ${check.id} repeats case id ${entry.id}`)
        ids.add(entry.id)
        if (!Number.isSafeInteger(entry.weight) || entry.weight < 1) problems.push(`check ${check.id} case ${entry.id} has weight ${entry.weight}`)
      }
      // The pre-state still stands in the copy: a case file that it satisfies
      // in full measures nothing the visible suite does not already measure.
      const discriminating = entries.some(entry => caseMismatches(copy, command, entry).length > 0)
      if (!discriminating) problems.push(`check ${check.id} cases ${relative}: the pre-state passes every case`)
    }
    rmSync(join(copy, 'src'), { recursive: true, force: true })
    cpSync(join(dir, 'reference', 'src'), join(copy, 'src'), { recursive: true })
    const ref = runTests(copy)
    if (ref.status !== 0) problems.push(`reference fails its tests: ${(ref.stdout + ref.stderr).split('\n').filter(line => /not ok|Error/.test(line)).slice(0, 3).join(' | ')}`)
    for (const check of cased) {
      const command = caseCommand(check)
      if (command === undefined) continue
      const entries = JSON.parse(readFileSync(join(dir, ...check.cases.split('/')), 'utf8'))
      const broken = entries
        .map(entry => ({ id: entry.id, mismatched: caseMismatches(copy, command, entry) }))
        .filter(one => one.mismatched.length > 0)
      if (broken.length > 0) {
        problems.push(`check ${check.id}: the reference misses ${broken.length} of ${entries.length} cases (${broken.slice(0, 3).map(one => `${one.id}:${one.mismatched.join('+')}`).join(', ')})`)
      }
    }
  } finally {
    rmSync(copy, { recursive: true, force: true })
  }
  if (problems.length > 0) {
    failures += 1
    console.error(`REJECT ${name}: ${problems.join('; ')}`)
  } else {
    const cases = caseCount > 0 ? ` cases=${caseCount}` : ''
    console.log(`admit ${task.id} tier=${task.tier} domain=${task.domain} heldOut=${task.heldOut}${cases}`)
  }
}
if (failures > 0) {
  console.error(`admit: ${failures} task(s) rejected`)
  process.exit(1)
}

/** RFC 3986 reference parsing, syntax-based normalization, and reference resolution. */

/** Appendix B: the five components of a URI reference, any of which may be absent. */
const URI_REFERENCE = /^(?:([^:/?#]+):)?(?:\/\/([^/?#]*))?([^?#]*)(?:\?([^#]*))?(?:#(.*))?$/u

/** Characters that never need percent-encoding, so an encoded one is decoded. */
const UNRESERVED = /^[A-Za-z0-9\-._~]$/u

/** Ports a scheme implies, which normalization drops when they are written out. */
const DEFAULT_PORT = { http: '80', https: '443', ws: '80', wss: '443', ftp: '21' }

/** A percent-encoding triplet with two hexadecimal digits. */
const TRIPLET = /%[0-9A-Fa-f]{2}/u

/** Raised for input the syntax rejects; the message is what the program reports. */
export class UriError extends Error {
  /**
   * @param message - the reported reason, without a position.
   */
  constructor(message) {
    super(message)
    this.name = 'UriError'
  }
}

/** ASCII-only lowercasing, so a Turkish or Greek locale cannot change a scheme or host. */
function lowerAscii(text) {
  let out = ''
  for (const character of text) {
    const code = character.codePointAt(0)
    out += code >= 0x41 && code <= 0x5A ? String.fromCharCode(code + 0x20) : character
  }
  return out
}

/**
 * Normalize percent-encodings in one component: uppercase every triplet's hex
 * digits, then decode the triplets that stand for an unreserved character.
 * @param text - the raw component.
 * @param subject - what the component is, for the error message.
 * @returns the component with its percent-encodings normalized.
 * @throws {UriError} when a `%` is not followed by two hexadecimal digits.
 */
export function normalizePercent(text, subject) {
  let out = ''
  for (let index = 0; index < text.length; index += 1) {
    if (text[index] !== '%') {
      out += text[index]
      continue
    }
    const triplet = text.slice(index, index + 3)
    if (!TRIPLET.test(triplet)) throw new UriError(`${subject} has a truncated percent-encoding`)
    const octet = Number.parseInt(triplet.slice(1), 16)
    const decoded = String.fromCharCode(octet)
    out += UNRESERVED.test(decoded) ? decoded : `%${triplet.slice(1).toUpperCase()}`
    index += 2
  }
  return out
}

/**
 * Split an authority into its userinfo, host, and port. The host runs from
 * after the last `@` to the `:` that starts the port, and a `:` inside an IPv6
 * literal's brackets is part of the host.
 * @param authority - the authority, without its leading `//`.
 * @returns the three parts, with `userinfo` and `port` absent when unwritten.
 */
export function splitAuthority(authority) {
  const at = authority.lastIndexOf('@')
  const userinfo = at === -1 ? undefined : authority.slice(0, at)
  const rest = authority.slice(at + 1)
  const bracket = rest.lastIndexOf(']')
  const colon = rest.indexOf(':', bracket === -1 ? 0 : bracket)
  if (colon === -1) return { userinfo, host: rest, port: undefined }
  return { userinfo, host: rest.slice(0, colon), port: rest.slice(colon + 1) }
}

/**
 * Parse a URI reference into its five components.
 * @param text - the reference.
 * @returns the components; `scheme`, `authority`, `query`, and `fragment` are absent when unwritten, and `path` is always a string.
 * @throws {UriError} when the reference does not match the generic syntax.
 */
export function parse(text) {
  const match = URI_REFERENCE.exec(text)
  if (match === null) throw new UriError('is not a URI reference')
  return { scheme: match[1], authority: match[2], path: match[3] ?? '', query: match[4], fragment: match[5] }
}

/**
 * RFC 3986 section 5.2.4: interpret `.` and `..` segments against the path,
 * discarding a `..` that would climb above the root.
 * @param path - the path to resolve.
 * @returns the path with no dot segments left.
 */
export function removeDotSegments(path) {
  const out = []
  let rest = path
  while (rest !== '') {
    if (rest.startsWith('../')) rest = rest.slice(3)
    else if (rest.startsWith('./')) rest = rest.slice(2)
    else if (rest.startsWith('/./')) rest = `/${rest.slice(3)}`
    else if (rest === '/.') rest = '/'
    else if (rest.startsWith('/../')) {
      rest = `/${rest.slice(4)}`
      out.pop()
    } else if (rest === '/..') {
      rest = '/'
      out.pop()
    } else if (rest === '.' || rest === '..') rest = ''
    else {
      const next = rest.indexOf('/', rest.startsWith('/') ? 1 : 0)
      const segment = next === -1 ? rest : rest.slice(0, next)
      out.push(segment)
      rest = next === -1 ? '' : rest.slice(next)
    }
  }
  return out.join('')
}

/** Rebuild a reference from its components, keeping an empty query or fragment visible. */
function recompose(parts) {
  let out = parts.scheme === undefined ? '' : `${parts.scheme}:`
  if (parts.authority !== undefined) out += `//${parts.authority}`
  out += parts.path
  if (parts.query !== undefined) out += `?${parts.query}`
  if (parts.fragment !== undefined) out += `#${parts.fragment}`
  return out
}

/** Reassemble an authority from the parts `splitAuthority` produced. */
function joinAuthority(userinfo, host, port) {
  return `${userinfo === undefined ? '' : `${userinfo}@`}${host}${port === undefined ? '' : `:${port}`}`
}

/**
 * Syntax-based normalization of parsed components: case, percent-encodings,
 * the default port, dot segments, and the empty path under an authority.
 * @param parts - the parsed components.
 * @returns the normalized components.
 * @throws {UriError} when a component carries a truncated percent-encoding.
 */
export function normalizeParts(parts) {
  const scheme = parts.scheme === undefined ? undefined : lowerAscii(parts.scheme)
  let authority
  if (parts.authority !== undefined) {
    const { userinfo, host, port } = splitAuthority(parts.authority)
    const normalizedPort = port === undefined || port === '' || port === DEFAULT_PORT[scheme] ? undefined : port
    authority = joinAuthority(
      userinfo === undefined ? undefined : normalizePercent(userinfo, 'the userinfo'),
      lowerAscii(normalizePercent(host, 'the host')),
      normalizedPort,
    )
  }
  let path = removeDotSegments(normalizePercent(parts.path, 'the path'))
  if (authority !== undefined && path === '') path = '/'
  return {
    scheme,
    authority,
    path,
    query: parts.query === undefined ? undefined : normalizePercent(parts.query, 'the query'),
    fragment: parts.fragment === undefined ? undefined : normalizePercent(parts.fragment, 'the fragment'),
  }
}

/**
 * Normalize one URI reference.
 * @param text - the reference.
 * @returns the normalized reference.
 * @throws {UriError} when the reference is not well formed.
 */
export function normalize(text) {
  return recompose(normalizeParts(parse(text)))
}

/** RFC 3986 section 5.2.3: graft a relative path onto the base's. */
function merge(base, path) {
  if (base.authority !== undefined && base.path === '') return `/${path}`
  const cut = base.path.lastIndexOf('/')
  return cut === -1 ? path : `${base.path.slice(0, cut + 1)}${path}`
}

/**
 * RFC 3986 section 5.2.2 in its strict form — a reference that repeats the
 * base's scheme is still absolute — followed by normalization of the target.
 * @param baseText - the base URI, which must carry a scheme.
 * @param referenceText - the reference resolved against it.
 * @returns the normalized target URI.
 * @throws {UriError} when either side is malformed or the base has no scheme.
 */
export function resolve(baseText, referenceText) {
  const base = parse(baseText)
  if (base.scheme === undefined) throw new UriError('the base has no scheme')
  const reference = parse(referenceText)
  let target
  if (reference.scheme !== undefined) {
    target = { ...reference, path: removeDotSegments(reference.path) }
  } else if (reference.authority !== undefined) {
    target = { scheme: base.scheme, authority: reference.authority, path: removeDotSegments(reference.path), query: reference.query, fragment: reference.fragment }
  } else if (reference.path === '') {
    target = {
      scheme: base.scheme,
      authority: base.authority,
      path: base.path,
      query: reference.query === undefined ? base.query : reference.query,
      fragment: reference.fragment,
    }
  } else {
    const path = reference.path.startsWith('/') ? reference.path : merge(base, reference.path)
    target = { scheme: base.scheme, authority: base.authority, path: removeDotSegments(path), query: reference.query, fragment: reference.fragment }
  }
  return recompose(normalizeParts(target))
}

#!/usr/bin/env node
/** The command: one mode word, one record per stdin line, one result per line. */

import { readFileSync } from 'node:fs'
import { normalize, resolve, UriError } from './uri.js'

/** Report one failure the way the specification words it, and stop. */
function fail(message) {
  process.stderr.write(`error: ${message}\n`)
  process.exit(2)
}

/** Every input line, with the trailing newline's empty tail dropped. */
function lines() {
  const text = readFileSync(0, 'utf8')
  const split = text.split('\n')
  if (split.length > 0 && split[split.length - 1] === '') split.pop()
  return split
}

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'normalize' && mode[0] !== 'resolve')) fail('usage: cli.js normalize|resolve')

const out = []
const input = lines()
for (let index = 0; index < input.length; index += 1) {
  const line = input[index]
  const at = `line ${index + 1}`
  try {
    if (mode[0] === 'normalize') {
      out.push(normalize(line))
      continue
    }
    const space = line.indexOf(' ')
    if (space === -1) fail(`${at}: expected a base and a reference`)
    out.push(resolve(line.slice(0, space), line.slice(space + 1)))
  } catch (error) {
    if (error instanceof UriError) fail(`${at}: ${error.message}`)
    throw error
  }
}
process.stdout.write(out.map(line => `${line}\n`).join(''))

